def module_to_xapi_vm_power_state(power_state: Any) -> object {
    vm_power_state_map = {
        "poweredon": "running",
        "poweredoff": "halted",
        "restarted": "running",
        "suspended": "suspended",
        "shutdownguest": "halted",
        "rebootguest": "running"
    };
    return vm_power_state_map.get(power_state);
}

